import numpy as np
from rcb_client import Robot
r=Robot(); o=r.get_obs(video='none'); qseed=np.array(o.meta['proprio']['now'][:7],float)
q0=np.array([0.,-2**-.5,2**-.5,0.]);
def mul(a,b):
 w,x,y,z=a; W,X,Y,Z=b
 return np.array([w*W-x*X-y*Y-z*Z,w*X+x*W+y*Z-z*Y,w*Y-x*Z+y*W+z*X,w*Z+x*Y-y*X+z*W])
for yaw in [0, -np.pi/4,np.pi/4,-np.pi/2,np.pi/2,np.pi]:
 rz=np.array([np.cos(yaw/2),0,0,np.sin(yaw/2)])
 qq=mul(rz,q0)
 for x in [.65,.70,.75,.80]:
  pose=[x,-.24,.335,*qq]
  a=r.ik({'tcp':pose},seed=qseed)
  print('yaw',round(yaw*180/np.pi), 'x',x,'ok',a['ok'],'err',a['error']['tcp']['pos_m'],a['error']['tcp']['rot_rad'])
print('other yaw low reach')
for z in [.30,.24,.18,.14]:
 for x in [.65,.70,.75,.80]:
  a=r.ik({'tcp':[x,-.24,z,*q0]},seed=qseed)
  print('down z',z,'x',x,'ok',a['ok'],'err',a['error']['tcp']['pos_m'])
