 for z in [.14,.16,.18,.22,.31,.335]:
  for j,q in enumerate(qs[:1]):
   a=r.ik({'tcp':[x,y,z,*q]},seed=qseed)
   if a['ok'] or (z==.14): print((x,y,z),'q',j,'ok',a['ok'],'err',a['error']['tcp'])
